const orders = [
  { customer_id: 1, amount: 50 },
  { customer_id: 2, amount: 30 },
  { customer_id: 1, amount: 75 },
  { customer_id: 3, amount: 20 },
  { customer_id: 2, amount: 45 },
];

const totals = orders.reduce((acc, order) => {
  acc[order.customer_id] = (acc[order.customer_id] || 0) + order.amount;
  return acc;
}, {});

Object.entries(totals).forEach(([id, total]) => {
  console.log(`Customer ${id}: $${total}`);
});
